template<typename T, size_t BlockCount>
class MemoryPool {
    union Node { T element; Node* next; };
    Node* freeList = nullptr;
    char storage[sizeof(Node) * BlockCount];
public:
    MemoryPool() {
        Node* pool = reinterpret_cast<Node*>(storage);
        for (size_t i = 0; i < BlockCount - 1; ++i) pool[i].next = &pool[i + 1];
        pool[BlockCount - 1].next = nullptr;
        freeList = pool;
    }
    T* allocate() {
        if (!freeList) throw std::bad_alloc();
        Node* node = freeList;
        freeList = freeList->next;
        return &(node->element);
    }
    void deallocate(T* ptr) {
        Node* node = reinterpret_cast<Node*>(ptr);
        node->next = freeList;
        freeList = node;
    }
};

def has_cycle(graph):
    visited = {node: 'WHITE' for node in graph}
    def dfs(node):
        visited[node] = 'GRAY'
        for neighbor in graph.get(node, []):
            if visited[neighbor] == 'GRAY': return True
            if visited[neighbor] == 'WHITE' and dfs(neighbor): return True
        visited[node] = 'BLACK'
        return False
    return any(dfs(node) for node in graph if visited[node] == 'WHITE')

